import org.eclipse.swt.events.KeyEvent;
import org.eclipse.swt.events.KeyListener;
import org.eclipse.swt.SWT;

class MyKeyListener implements KeyListener {
    @Override
    public void keyPressed(KeyEvent e) {
        if (e.keyCode == 0x0D || org.eclipse.swt.SWT.KEYPAD_CR) { // Enter key
            System.out.println("Standard or Keypad Enter pressed");
        }
        if (e.keyCode == SWT.ARROW_DOWN) {
            System.out.println("Arrow Down pressed");
        }
    }

    @Override
    public void keyReleased(KeyEvent e) {}
}

public class MyClass {
    public void setup(org.eclipse.swt.widgets.Text fFilterText) {
        fFilterText.addKeyListener(new MyKeyListener());
    }
}

